import { projectTool } from './tool.js';
export const name = 'project-coordinator';
export const inject = ['tools', 'systemPrompt'];
export function apply(ctx) {
  ctx.tools.guard(exec => {
    const service = ctx.get('projects');
    return service?.available ? service.guard(exec) : 'Project Host is unavailable.';
  });
  projectTool(ctx, { name: 'project_review', method: 'review', description: 'Inspect a settled member result and accept or return the exact current report with actual evidence. Dependencies wait for accepted results, not native task completion. Return defects to the same workstream through project_delegate.', parameters: { workstreamId: { type: 'string', required: true }, delegationRef: { type: 'string', required: true }, reportId: { type: 'string', required: true }, decision: { type: 'string', enum: ['accepted', 'returned'], required: true }, reason: { type: 'string', required: true }, evidence: { type: 'array', items: { type: 'string' }, required: true } } });
  projectTool(ctx, { name: 'project_request', method: 'acceptRequest', description: 'Record one human goal, restrictions, completion conditions and original authorization ceiling. Use disposition discussing for tentative ideas: they cannot execute. Use queued only when the user authorized development; multiple accepted requirements may execute together; only conflicting work waits. Use requestId to revise the same goal, preserving its queue position and effective restrictions. Only actual human input creates or revises requirements. No user form or extra confirmation is needed.', parameters: { requestId: { type: 'string' }, disposition: { type: 'string', enum: ['discussing', 'queued'] }, title: { type: 'string', required: true }, goal: { type: 'string', required: true }, constraints: { type: 'array', items: { type: 'string' } }, conditions: { type: 'array', items: { type: 'string' }, required: true }, scopeCeiling: { type: 'string', enum: ['readonly', 'research', 'docs', 'development'], required: true }, writePaths: { type: 'array', items: { type: 'string' } } } });
  projectTool(ctx, { name: 'project_queue', method: 'queueRequest', description: 'Apply the human user’s queue instruction to an existing requirement. enqueue approves a discussed or cancelled goal, or explicitly rejoins a released historical goal that needs review; it preserves Project pause. move changes only waiting order (beforeRequestId, or end when absent). cancel stops that requirement and its owned work while retaining records. resume explicitly continues an accepted active or queued requirement; it never resumes a cancelled or released historical goal. Supply the current revision. Settlements and host queue messages cannot authorize queue changes.', parameters: { requestId: { type: 'string', required: true }, requestRevision: { type: 'number', required: true }, action: { type: 'string', enum: ['enqueue', 'move', 'cancel', 'resume'], required: true }, beforeRequestId: { type: 'string' } } });
  projectTool(ctx, { name: 'project_ask', method: 'askHuman', description: 'Ask the human user ONE specific question about one requirement when its work cannot proceed without their answer or decision. The host shows it in the Project panel and header; the user’s next message is the answer. A requirement holds at most one question: repeating it is reused, a different one replaces it. Give a few short options only when they fit, and say in ifUnanswered what you will do meanwhile. Set clear to withdraw a question the user no longer needs to answer. Not for confirming that work should continue.', parameters: { requestId: { type: 'string', required: true }, question: { type: 'string', description: 'One sentence.' }, options: { type: 'array', items: { type: 'string' }, description: 'At most six short answers.' }, ifUnanswered: { type: 'string', description: 'What happens if the user does not answer.' }, clear: { type: 'boolean' } } });
  projectTool(ctx, { name: 'project_standby', method: 'standby', finish: true, description: 'End this coordinator turn silently, with no message to the user. Only when a host notice (a member finished, the next requirement was activated, the host retried a summary) started the turn, the user wrote nothing in it, and nothing needs saying: no delivery, no question, no failure or blocker. Do the bookkeeping first (todo_write, delegating the next stage), then call this. The host refuses it when the user is waited on, a delivery is due, or the active requirement has nothing running or queued.', parameters: { note: { type: 'string', description: 'A few words for the record, such as "stage 2 delegated".' } } });
  projectTool(ctx, { name: 'project_deliver', method: 'deliver', description: 'Explicitly declare a handover for one current requirement version, then give its final user-facing reply in this turn. Read reports first and reference their exact workstream/delegation/report identity. completed is final acceptance with inspection evidence, persisted only with the visible handover; it requires all necessary work, matching native settlements and validation; partial preserves explicit unmet conditions. remainingIssues lists only required work or conditions that are still unmet, and makes the handover partial: leave it empty for completed and put remarks that do not block the goal in the summary. Progress messages and reading reports never count as a handover. The host binds the real reply only after durable successful turn completion.', parameters: { requestId: { type: 'string', required: true }, requestRevision: { type: 'number', required: true }, summary: { type: 'string', required: true }, outcome: { type: 'string', enum: ['completed', 'partial'], required: true }, decision: { type: 'string', description: 'One or two sentences: what was decided or changed and why, including any user-approved exception to Project rules. Appended to the Project decision log.' }, evidence: { type: 'array', items: { type: 'string' } }, remainingIssues: { type: 'array', items: { type: 'string' }, description: 'Required work or conditions that are still unmet. Leave empty when outcome is completed; remarks that do not block the goal belong in the summary.' }, reportRefs: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { workstreamId: { type: 'string', required: true }, delegationRef: { type: 'string', required: true }, reportId: { type: 'string' } } } }, terminalRefs: { type: 'array', items: { type: 'object', additionalProperties: false, properties: { workstreamId: { type: 'string', required: true }, delegationRef: { type: 'string', required: true }, runId: { type: 'string', required: true } } } } } });
  projectTool(ctx, { name: 'project_read_store', method: 'readStoreTool', description: 'Read notes.md, preferences.md, charter.md, decisions.md or docs/<path> in this Project. notes returns authoritative Project facts (bound repository versus materials directory), prior requirements, work, pending results (handovers come back as one line each unless requestId names a requirement, whose handovers are complete). Empty records mean no saved Project history, not an empty repository. Repository contents require delegated inspection; no repository or internal access here.', parameters: { path: { type: 'string', required: true }, requestId: { type: 'string' }, query: { type: 'string' }, workstreamId: { type: 'string' }, cursor: { type: 'string' }, fullNotes: { type: 'boolean', description: 'Read all of the user notes; by default only the first 4000 characters come back.' } } });
  projectTool(ctx, { name: 'project_delegate', method: 'delegate',
    description: 'Delegate actual work authorized by the current user. Supply the original workstreamId to continue its fixed worker Session. queued means not started. Preserve all restrictions in brief. readonly has no shell or repository writes; research adds read-only web search and page reading to that; docs writes only declared repository document paths and Project deliverables. isolate is only for explicitly requested independent parallel development.',
    parameters: { replacesWorkstreamId: { type: 'string', description: 'Explicitly replace a truly failed, drained work for this same requirement; preserves the original member and failure history.' }, replacementReason: { type: 'string' }, requestId: { type: 'string', description: 'The whole user goal declared by project_request; settlement-driven next stages remain with this goal.' }, requestRevision: { type: 'number' }, blockedBy: { type: 'array', items: { type: 'string' }, description: 'Existing workstream IDs whose actual completion is required before this work starts.' }, workstreamId: { type: 'string' }, title: { type: 'string' }, brief: { type: 'string', required: true }, scope: { type: 'string', enum: ['readonly', 'research', 'docs', 'development'], required: true }, writePaths: { type: 'array', items: { type: 'string' } }, isolate: { type: 'boolean' } } });
  projectTool(ctx, { name: 'project_stop', method: 'stopTool', description: 'Stop one workstream and its owned activity; omit workstreamId only to stop all Project background work. This interrupts work, does not send another worker prompt, and does not automatically restart.', parameters: { workstreamId: { type: 'string' } } });
  ctx.systemPrompt.section({ name: 'project:scope', order: 10300, interpolate: false, text: ({ agent }) => ctx.get('projects')?.contextFor(agent?.id) ?? '' });
  ctx.systemPrompt.section({ name: 'project:charter', order: 10305, interpolate: false, text: ({ agent }) => ctx.get('projects')?.charterFor(agent?.id) ?? '' });
  ctx.systemPrompt.section({ name: 'project:decisions', order: 10315, interpolate: false, text: ({ agent }) => ctx.get('projects')?.decisionsFor(agent?.id) ?? '' });
  ctx.systemPrompt.section({ name: 'project:preferences', order: 10310, interpolate: false, text: ({ agent }) => ctx.get('projects')?.preferencesFor(agent?.id) ?? '' });
}
